public class PiePlot_initialise_TriageGen0Test {

    private PiePlot piePlot;
    private Graphics2D g2;
    private Rectangle2D plotArea;
    private Integer index;
    private PlotRenderingInfo info;
    private PieDataset dataset;

    @Before
    public void setUp() {
        piePlot = new PiePlot();
        g2 = mock(Graphics2D.class);
        plotArea = new Rectangle2D.Double(0, 0, 100, 100);
        index = 0;
        info = mock(PlotRenderingInfo.class);
        dataset = mock(PieDataset.class);
    }

    @Test
    public void testInitialise() {
        // Arrange
        double expectedTotal = 100.0;
        double startAngle = 15.0;

        // Mock dataset behavior for DatasetUtilities.calculatePieDatasetTotal
        // Note: DatasetUtilities usually iterates through the dataset. 
        // We mock the dataset to return specific values to satisfy the calculation.
        when(dataset.getValues()).thenReturn(new double[]{60.0, 40.0});
        when(dataset.getKeys()).thenReturn(new Object[]{"A", "B"});

        piePlot.setDataset(dataset);
        piePlot.setStartAngle(startAngle);

        // Act
        PiePlotState state = piePlot.initialise(g2, plotArea, piePlot, index, info);

        // Assert
        assertNotNull("State should not be null", state);
        assertEquals("Passes required should be 2", 2, state.getPassesRequired());
        assertEquals("Total should match dataset sum", expectedTotal, state.getTotal(), 0.001);
        assertEquals("Latest angle should match start angle", startAngle, state.getLatestAngle(), 0.001);
    }

    @Test
    public void testInitialiseWithZeroTotal() {
        // Arrange
        when(dataset.getValues()).thenReturn(new double[]{0.0, 0.0});
        when(dataset.getKeys()).thenReturn(new Object[]{"A", "B"});
        piePlot.setDataset(dataset);
        piePlot.setStartAngle(0.0);

        // Act
        PiePlotState state = piePlot.initialise(g2, plotArea, piePlot, index, info);

        // Assert
        assertNotNull(state);
        assertEquals(0.0, state.getTotal(), 0.001);
    }
}
